insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('inicio','budi',1,'Punto de partida Puerto Domínguez','Puerto Domínguez',330,250,'inicio','9:00–18:00',array['Aquí se recoge el mapa, se conoce a quien guía y se reciben las indicaciones para recorrer el territorio con respeto.','El Budi es un lago de agua salobre que se comunica con el mar. Sus orillas son territorio lafkenche, la gente del mar.']::text[],'Mari mari','Saludo. Se dice al llegar, mirando a la persona.','Red Lafken Budi','Coordinación de la ruta, 14 familias socias',false)
  on conflict (id) do update set n=excluded.n, name=excluded.name, sector=excluded.sector, x=excluded.x, y=excluded.y, glyph=excluded.glyph, open_hours=excluded.open_hours, story=excluded.story, word=excluded.word, word_meaning=excluded.word_meaning, host_role=excluded.host_role, boat=excluded.boat;
