insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('witral','budi',2,'Witral Quilaqueo','Camino a Collileufu',300,322,'witral','10:00–19:00',array['En la ruka de tejido se trabaja la lana de oveja de la comunidad: se esquila, se hila y se tiñe con plantas del entorno.','Cada diseño tiene nombre y significado. Rosa los explica mientras teje; pregunta antes de fotografiar las piezas en proceso.']::text[],'Witral','Telar vertical mapuche. También se llama así al tejido que sale de él.','Rosa Quilaqueo','Tejedora, aprendió de su abuela',false)
