insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('cocina','budi',3,'Cocina Kutralwe','Collileufu',228,372,'cocina','12:00–17:00',array['Se cocina a leña con lo que da el mar y la huerta: cochayuyo, luche, papas, mültrün y mote.','El almuerzo se sirve en la ruka, junto al fogón. Se reserva con anticipación porque se prepara para el número de personas.']::text[],'Kutral','Fuego. Kutralwe es el lugar donde está el fuego.','Familia Llanquinao','Cocina lafkenche de temporada',false)
