insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('nocha','budi',4,'Cestería en ñocha','Humedal de Collileufu',138,356,'nocha','10:00–18:00',array['La ñocha se corta en verano, se seca al sol y se trenza a mano. Un canasto mediano toma dos días de trabajo.','Elsa enseña a reconocer la planta en el humedal y a trenzar la base de un canasto pequeño.']::text[],'Ñocha','Fibra vegetal de los humedales con la que se tejen canastos y esteras.','Elsa Calfuqueo','Cestera, recolecta en el humedal',false)
