insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('mirador','budi',5,'Mirador del Budi','Ribera poniente',70,250,'mirador','Todo el día',array['Desde la loma se ve el lago completo y, en días claros, la línea del mar.','Al atardecer llegan bandadas de cisne de cuello negro. Mantén distancia y silencio; es zona de nidificación.']::text[],'Lafken','Mar, o una gran extensión de agua. Lafkenche: la gente del mar.',null,null,false)
