insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('muelle','budi',6,'Muelle y navegación','Ribera norte',118,150,'bote','10:00–20:00',array['Antes de los caminos, el lago era la ruta entre comunidades. Hoy se navega en bote a motor y, en fechas especiales, en wampo.','Desde aquí sale el traslado a Isla Huapi, siguiente parada de la ruta.']::text[],'Wampo','Canoa tradicional tallada en un tronco.','Juan Millaqueo','Botero, navega el lago hace 25 años',false)
  on conflict (id) do update set n=excluded.n, name=excluded.name, sector=excluded.sector, x=excluded.x, y=excluded.y, glyph=excluded.glyph, open_hours=excluded.open_hours, story=excluded.story, word=excluded.word, word_meaning=excluded.word_meaning, host_role=excluded.host_role, boat=excluded.boat;
