insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('ruka','budi',7,'Ruka Isla Huapi','Isla Huapi',192,173,'ruka','Recepción 15:00–21:00',array['La ruka se construye en minga, con paja de la vega. Al centro arde el fuego y alrededor se conversa.','En la noche, la familia comparte relatos del territorio. Es una conversación, no una presentación: se escucha y se pregunta.']::text[],'Ruka','Casa tradicional de paja y madera, con el fogón al centro.','Familia Ancamil','Hospedaje en ruka y conversación',true)
