insert into public.stops (id,route_id,n,name,sector,x,y,glyph,open_hours,story,word,word_meaning,host_name,host_role,boat) values ('lawen','budi',8,'Huerta y lawen','Ribera nororiente',284,132,'lawen','10:00–18:00',array['La huerta mezcla hortalizas, frutales y plantas medicinales. Marta muestra cómo se reconocen y para qué se usan.','Algunas plantas no se venden: se regalan o se usan solo en la familia. Se respeta cuando lo dice.']::text[],'Lawen','Planta medicinal; también el remedio que se prepara con ella.','Marta Curiñir','Huertera y conocedora de plantas',true)
